package com.grad.ventora.documentation.service.impl;

import com.grad.ventora.documentation.dto.*;
import com.grad.ventora.documentation.entity.*;
import com.grad.ventora.documentation.repository.*;
import com.grad.ventora.documentation.service.DocumentationService;
import com.grad.ventora.exception.exceptions.ResourceNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.text.Normalizer;
import java.util.*;
import java.util.regex.Pattern;

@Service
@RequiredArgsConstructor
@Transactional
public class DocumentationServiceImpl implements DocumentationService {
 private final DocumentationVersionRepository versions;
 private final DocumentationCategoryRepository categories;
 private final DocumentationArticleRepository articles;
 private final DocumentationPageContentRepository pages;
 private DocumentationVersion version(Long id){return versions.findById(id).orElseThrow(()->new ResourceNotFoundException("Documentation version not found"));}
 private DocumentationCategory category(Long id){return categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Documentation category not found"));}
 private DocumentationArticle articleEntity(Long id){return articles.findById(id).orElseThrow(()->new ResourceNotFoundException("Documentation article not found"));}
 private DocumentationVersion selectedVersion(String slug){
  if(slug!=null&&!slug.isBlank()) return versions.findBySlug(slug).filter(v->Boolean.TRUE.equals(v.getActive())).orElseThrow(()->new ResourceNotFoundException("Active documentation version not found"));
  return versions.findFirstByIsLatestTrueAndActiveTrue().orElseThrow(()->new ResourceNotFoundException("No active latest documentation version configured"));
 }
 private DocumentationVersionResponse versionDto(DocumentationVersion v){return new DocumentationVersionResponse(v.getId(),v.getName(),v.getSlug(),v.getDescription(),v.getIsLatest(),v.getActive(),v.getCreatedAt(),v.getUpdatedAt());}
 private DocumentationCategoryResponse categoryDto(DocumentationCategory c){return new DocumentationCategoryResponse(c.getId(),c.getName(),c.getSlug(),c.getDescription(),c.getDisplayOrder(),c.getActive(),articles.countByCategory_Id(c.getId()));}
 private DocumentationArticleSummary summary(DocumentationArticle a){return new DocumentationArticleSummary(a.getId(),a.getTitle(),a.getSlug(),a.getDescription(),a.getDisplayOrder(),a.getCategory().getName(),a.getCategory().getSlug(),a.getVersion().getName(),a.getVersion().getSlug());}
 private String anchor(String s){String n=Normalizer.normalize(s.toLowerCase(Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}",""); n=n.replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)",""); return n.isBlank()?"section":n;}
 private DocumentationArticleResponse articleDto(DocumentationArticle a,boolean navigation){
  List<DocumentationBlockResponse> blocks=a.getContentBlocks().stream().sorted(Comparator.comparing(DocumentationContentBlock::getDisplayOrder)).map(b->new DocumentationBlockResponse(b.getId(),b.getType(),b.getContent(),b.getDisplayOrder())).toList();
  List<DocumentationTocItem> toc=new ArrayList<>(); Set<String> used=new HashSet<>();
  for(var b:blocks) if(b.type()==DocumentationBlockType.HEADING){Object t=b.content().get("text"); if(t!=null){String title=t.toString();int level=1;try{level=Integer.parseInt(String.valueOf(b.content().getOrDefault("level",1)));}catch(Exception ignored){} String base=anchor(title),key=base;int i=2;while(!used.add(key))key=base+"-"+i++;toc.add(new DocumentationTocItem(title,level,key));}}
  List<DocumentationArticleSummary> related=a.getRelatedArticles().stream().filter(x->x.getStatus()==DocumentationArticleStatus.PUBLISHED).map(this::summary).toList();
  DocumentationArticleSummary prev=null,next=null;
  if(navigation){List<DocumentationArticle> siblings=articles.findAllByVersion_IdAndCategory_IdAndStatusOrderByDisplayOrderAsc(a.getVersion().getId(),a.getCategory().getId(),DocumentationArticleStatus.PUBLISHED);int idx=-1;for(int i=0;i<siblings.size();i++)if(siblings.get(i).getId().equals(a.getId()))idx=i;if(idx>0)prev=summary(siblings.get(idx-1));if(idx>=0&&idx+1<siblings.size())next=summary(siblings.get(idx+1));}
  return new DocumentationArticleResponse(a.getId(),a.getTitle(),a.getSlug(),a.getDescription(),a.getCategory().getId(),a.getCategory().getName(),a.getCategory().getSlug(),a.getVersion().getId(),a.getVersion().getName(),a.getVersion().getSlug(),a.getDisplayOrder(),a.getStatus(),a.getPublishedAt(),blocks,toc,related,prev,next,a.getCreatedAt(),a.getUpdatedAt());
 }
 @Override @Transactional(readOnly=true) public List<DocumentationVersionResponse> versions(boolean admin){return (admin?versions.findAll(Sort.by(Sort.Direction.DESC,"createdAt")):versions.findAll().stream().filter(v->Boolean.TRUE.equals(v.getActive())).sorted(Comparator.comparing(DocumentationVersion::getCreatedAt).reversed()).toList()).stream().map(this::versionDto).toList();}
 @Override public DocumentationVersionResponse saveVersion(Long id,DocumentationVersionRequest r){DocumentationVersion v=id==null?new DocumentationVersion():version(id);if(versions.existsBySlug(r.slug())&&(v.getId()==null||!Objects.equals(v.getSlug(),r.slug())))throw new IllegalArgumentException("Documentation version slug already exists");v.setName(r.name());v.setSlug(r.slug());v.setDescription(r.description());if(r.active()!=null)v.setActive(r.active());if(v.getIsLatest()==null)v.setIsLatest(false);if(Boolean.TRUE.equals(v.getIsLatest())&&!Boolean.TRUE.equals(v.getActive()))throw new IllegalArgumentException("Latest version must be active");return versionDto(versions.save(v));}
 @Override public DocumentationVersionResponse setLatest(Long id){DocumentationVersion target=version(id);if(!Boolean.TRUE.equals(target.getActive()))throw new IllegalStateException("Cannot set an inactive version as latest");versions.findAll().forEach(v->v.setIsLatest(v.getId().equals(id)));return versionDto(target);}
 @Override public DocumentationVersionResponse setVersionActive(Long id,boolean active){DocumentationVersion v=version(id);if(!active&&Boolean.TRUE.equals(v.getIsLatest())){DocumentationVersion replacement=versions.findAll().stream().filter(x->!x.getId().equals(id)&&Boolean.TRUE.equals(x.getActive())).findFirst().orElseThrow(()->new IllegalStateException("Activate another version before deactivating the latest version"));replacement.setIsLatest(true);v.setIsLatest(false);}v.setActive(active);return versionDto(v);}
 @Override public void deleteVersion(Long id){DocumentationVersion v=version(id);if(articles.existsByVersion_Id(id))throw new IllegalStateException("Cannot delete a version that has articles");versions.delete(v);}
 @Override @Transactional(readOnly=true) public List<DocumentationCategoryResponse> categories(boolean admin){return (admin?categories.findAllByOrderByDisplayOrderAsc():categories.findAllByActiveTrueOrderByDisplayOrderAsc()).stream().map(this::categoryDto).toList();}
 @Override public DocumentationCategoryResponse saveCategory(Long id,DocumentationCategoryRequest r){DocumentationCategory c=id==null?new DocumentationCategory():category(id);if(categories.existsBySlug(r.slug())&&(c.getId()==null||!Objects.equals(c.getSlug(),r.slug())))throw new IllegalArgumentException("Documentation category slug already exists");if(categories.existsByNameIgnoreCase(r.name())&&(c.getId()==null||!c.getName().equalsIgnoreCase(r.name())))throw new IllegalArgumentException("Documentation category name already exists");c.setName(r.name());c.setSlug(r.slug());c.setDescription(r.description());c.setDisplayOrder(r.displayOrder());if(r.active()!=null)c.setActive(r.active());return categoryDto(categories.save(c));}
 @Override public void setCategoryActive(Long id,boolean active){category(id).setActive(active);}
 @Override public void deleteCategory(Long id){DocumentationCategory c=category(id);if(articles.existsByCategory_Id(id))throw new IllegalStateException("Cannot delete a category that has articles");categories.delete(c);}
 private Pageable pageable(int page,int size){return PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),50),Sort.by("displayOrder").ascending().and(Sort.by("createdAt").descending()));}
 @Override @Transactional(readOnly=true) public Page<DocumentationArticleSummary> articles(String versionSlug,String categorySlug,int page,int size){DocumentationVersion v=selectedVersion(versionSlug);Page<DocumentationArticle> result;if(categorySlug!=null&&!categorySlug.isBlank())result=articles.findByVersion_SlugAndStatusAndCategory_SlugAndCategory_ActiveTrue(v.getSlug(),DocumentationArticleStatus.PUBLISHED,categorySlug,pageable(page,size));else result=articles.findByVersion_SlugAndStatusAndCategory_ActiveTrue(v.getSlug(),DocumentationArticleStatus.PUBLISHED,pageable(page,size));return result.map(this::summary);}
 @Override @Transactional(readOnly=true) public Page<DocumentationArticleResponse> adminArticles(String search,String versionSlug,int page,int size){Pageable pg=pageable(page,size);String q=search==null?"":search.toLowerCase(Locale.ROOT);List<DocumentationArticle> all=(versionSlug==null||versionSlug.isBlank()?articles.findAll(Sort.by("displayOrder").ascending()):articles.findAllByVersion_Slug(versionSlug));List<DocumentationArticle> filtered=all.stream().filter(a->q.isBlank()||a.getTitle().toLowerCase(Locale.ROOT).contains(q)||Optional.ofNullable(a.getDescription()).orElse("").toLowerCase(Locale.ROOT).contains(q)).toList();int from=Math.min((int)pg.getOffset(),filtered.size()),to=Math.min(from+pg.getPageSize(),filtered.size());List<DocumentationArticleResponse> list=filtered.subList(from,to).stream().map(a->articleDto(a,false)).toList();return new PageImpl<>(list,pg,filtered.size());}
 @Override @Transactional(readOnly=true) public DocumentationArticleResponse article(String versionSlug,String slug){DocumentationVersion v=selectedVersion(versionSlug);DocumentationArticle a=articles.findByVersion_SlugAndSlugAndStatusAndCategory_ActiveTrue(v.getSlug(),slug,DocumentationArticleStatus.PUBLISHED).orElseThrow(()->new ResourceNotFoundException("Published documentation article not found"));return articleDto(a,true);}
 @Override @Transactional(readOnly=true) public DocumentationArticleResponse adminArticle(Long id){return articleDto(articleEntity(id),false);}
 @Override public DocumentationArticleResponse saveArticle(Long id,DocumentationArticleRequest r){DocumentationArticle a=id==null?new DocumentationArticle():articleEntity(id);DocumentationCategory c=category(r.categoryId());DocumentationVersion v=version(r.versionId());if(articles.existsByVersion_IdAndSlug(v.getId(),r.slug())&&(a.getId()==null||!Objects.equals(a.getVersion().getId(),v.getId())||!Objects.equals(a.getSlug(),r.slug())))throw new IllegalArgumentException("Article slug already exists in this version");if(!Boolean.TRUE.equals(c.getActive()))throw new IllegalArgumentException("Cannot assign an article to an inactive category");a.setTitle(r.title());a.setSlug(r.slug());a.setDescription(r.description());a.setCategory(c);a.setVersion(v);a.setDisplayOrder(r.displayOrder());a.getContentBlocks().clear();for(DocumentationBlockRequest br:r.contentBlocks()){DocumentationContentBlock block=new DocumentationContentBlock();block.setArticle(a);block.setType(br.type());block.setContent(br.content());block.setDisplayOrder(br.displayOrder());a.getContentBlocks().add(block);}a.getRelatedArticles().clear();if(r.relatedArticleIds()!=null)for(Long rid:r.relatedArticleIds()){if(a.getId()!=null&&a.getId().equals(rid))throw new IllegalArgumentException("An article cannot be related to itself");DocumentationArticle related=articleEntity(rid);if(!related.getVersion().getId().equals(v.getId()))throw new IllegalArgumentException("Related articles must belong to the same version");a.getRelatedArticles().add(related);}if(a.getStatus()==null)a.setStatus(DocumentationArticleStatus.DRAFT);return articleDto(articles.save(a),false);}
 @Override public DocumentationArticleResponse publish(Long id){DocumentationArticle a=articleEntity(id);if(!Boolean.TRUE.equals(a.getVersion().getActive()))throw new IllegalStateException("Cannot publish an article in an inactive version");if(!Boolean.TRUE.equals(a.getCategory().getActive()))throw new IllegalStateException("Cannot publish an article in an inactive category");if(a.getTitle()==null||a.getTitle().isBlank()||a.getContentBlocks().isEmpty())throw new IllegalArgumentException("Article must have a title and at least one content block before publishing");a.setStatus(DocumentationArticleStatus.PUBLISHED);if(a.getPublishedAt()==null)a.setPublishedAt(java.time.LocalDateTime.now());return articleDto(a,false);}
 @Override public DocumentationArticleResponse unpublish(Long id){DocumentationArticle a=articleEntity(id);a.setStatus(DocumentationArticleStatus.DRAFT);return articleDto(a,false);}
 @Override public void deleteArticle(Long id){articles.delete(articleEntity(id));}
 @Override @Transactional(readOnly=true) public Page<DocumentationArticleSummary> search(String query,String versionSlug,int page,int size){if(query==null||query.isBlank())return Page.empty(pageable(page,size));DocumentationVersion v=selectedVersion(versionSlug);Page<DocumentationArticle> p=articles.findByVersion_SlugAndStatusAndCategory_ActiveTrueAndTitleContainingIgnoreCaseOrVersion_SlugAndStatusAndCategory_ActiveTrueAndDescriptionContainingIgnoreCase(v.getSlug(),DocumentationArticleStatus.PUBLISHED,query,v.getSlug(),DocumentationArticleStatus.PUBLISHED,query,pageable(page,size));return p.map(this::summary);}
 @Override @Transactional(readOnly=true) public DocumentationPageContentResponse pageContent(){return pages.findFirstByOrderByIdAsc().map(this::pageDto).orElse(null);}
 private DocumentationPageContentResponse pageDto(DocumentationPageContent p){return new DocumentationPageContentResponse(p.getId(),p.getHeroTitle(),p.getHeroDescription(),p.getSearchPlaceholder(),p.getNeedHelpTitle(),p.getNeedHelpDescription(),p.getGetStartedLabel(),p.getGetStartedUrl(),p.getCreatedAt(),p.getUpdatedAt());}
 @Override public DocumentationPageContentResponse savePageContent(DocumentationPageContentRequest r){DocumentationPageContent p=pages.findFirstByOrderByIdAsc().orElseGet(DocumentationPageContent::new);p.setHeroTitle(r.heroTitle());p.setHeroDescription(r.heroDescription());p.setSearchPlaceholder(r.searchPlaceholder());p.setNeedHelpTitle(r.needHelpTitle());p.setNeedHelpDescription(r.needHelpDescription());p.setGetStartedLabel(r.getStartedLabel());p.setGetStartedUrl(r.getStartedUrl());return pageDto(pages.save(p));}
}
